## 4. `src/Diag.gs` — pairing helper (optional, non-blocking)

Skip this if §1–§3 are pushed and verified and there is no time left. Manually pairing ~24 start rows against ~24 completion rows per day on the Sheet is tedious enough that it will not get done, which is the only argument for it.

```js
/** Unpaired collect-start rows in the last `days` (default 3). Read-only. */
function diag_collect_timeouts() {
  var days = 3;
  var sh = sheet_(SHEET.healthTab);
  var last = sh.getLastRow();
  if (last < 2) {
    console.log('health tab empty');
    return;
  }
  var n = last - 1;
  var ts = sh.getRange(2, 1, n, 1).getValues();
  var kinds = sh.getRange(2, 2, n, 1).getValues();
  var cutoff = Date.now() - days * 864e5;
  var openStart = null;
  var unpaired = 0;
  for (var i = 0; i < n; i++) {
    var kind = String(kinds[i][0] || '');
    var when = ts[i][0];
    var t = when instanceof Date ? when.getTime() : Date.parse(String(when));
    if (!t || t < cutoff) continue;
    if (kind === 'collect-start') {
      if (openStart) {
        console.log('unpaired collect-start: ' + openStart);
        unpaired++;
      }
      openStart = String(when);
    } else if (kind === 'collect') {
      openStart = null;
    }
  }
  if (openStart) console.log('unpaired collect-start (most recent, may be in flight): ' + openStart);
  console.log('unpaired collect-start rows in last ' + days + 'd: ' + unpaired);
}
```

Assumes `health` column A is `timestamp` and column B is `kind` per `HEALTH_HEADERS_`. **Read the header row and confirm before trusting the column indices** — do not hardcode against this spec's assumption. The most recent open start is reported separately because a collect in flight looks identical to a timeout until it finishes.

Zero-arg, no writes, not added to `test_all`.

